import { randomUUID } from 'node:crypto';
import { performance } from 'node:perf_hooks';
import type { Clock, ClockReceipt } from '../domain/contracts.js';
import { clockReceiptSchema } from '../domain/schemas.js';

export const systemClock: Clock = { wallNow: () => Date.now(), monotonicNow: () => performance.now() };
/** A receipt is generated by the caller-owned clock, never from provider timestamps. */
export function captureClock(clock: Clock, processEpoch: string): ClockReceipt {
  return clockReceiptSchema.parse({ id: randomUUID(), wallMs: clock.wallNow(), monotonicMs: clock.monotonicNow(), processEpoch });
}
